#include <vector>
#include <cmath>
#include <algorithm>
#include <limits>

struct Node {
    double x = 0.f;
    double y = 0.f;
    Node* parent = nullptr;
    float h_value = std::numeric_limits<float>::max();
    float g_value = 0.0;
    bool visited = false;
    std::vector<Node*> neighbors;
};

struct Graph {
    std::vector<Node> nodes;
};

float distance(Node a, Node b) {
    return std::sqrt(std::pow(a.x - b.x, 2) + std::pow(a.y - b.y, 2));
}

std::vector<Node> a_star_search(Graph& graph, int start_idx, int end_idx) {
    Node* start_node = &graph.nodes[start_idx];
    Node* end_node = &graph.nodes[end_idx];

    std::vector<Node*> open_list;
    open_list.push_back(start_node);
    start_node->g_value = 0;
    start_node->h_value = distance(*start_node, *end_node);

    while (!open_list.empty()) {
        auto it = std::min_element(open_list.begin(), open_list.end(), [](Node* a, Node* b) {
            return (a->g_value + a->h_value) < (b->g_value + b->h_value);
        });
        Node* current = *it;
        open_list.erase(it);

        if (current == end_node) {
            std::vector<Node> path;
            while (current != nullptr) {
                path.push_back(*current);
                current = current->parent;
            }
            return path;
        }

        current->visited = true;
        for (Node* neighbor : current->neighbors) {
            if (neighbor->visited) continue;
            float tentative_g = current->g_value + distance(*current, *neighbor);
            if (tentative_g < neighbor->g_value || neighbor->g_value == 0 && neighbor != start_node) {
                neighbor->parent = current;
                neighbor->g_value = tentative_g;
                neighbor->h_value = distance(*neighbor, *end_node);
                if (std::find(open_list.begin(), open_list.end(), neighbor) == open_list.end()) {
                    open_list.push_back(neighbor);
                }
            }
        }
    }
    return {};
}

int main() {
    Graph g;
    g.nodes.push_back({0, 0});
    g.nodes.push_back({1, 0});
    g.nodes.push_back({1, 1});
    g.nodes[0].neighbors.push_back(&g.nodes[1]);
    g.nodes[1].neighbors.push_back(&g.nodes[0]);
    g.nodes[1].neighbors.push_back(&g.nodes[2]);
    g.nodes[2].neighbors.push_back(&g.nodes[1]);

    auto path = a_star_search(g, 0, 2);
    return path.size() == 3 ? 0 : 1;
}

